using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
internal static class WorkflowsAcceptance {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 internal static string Image(string folder){string path=Path.Combine(folder,"project-cover.png");using(var bitmap=new System.Drawing.Bitmap(640,180)){using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){graphics.Clear(System.Drawing.Color.FromArgb(50,42,28));using(var brush=new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(246,173,66)))graphics.FillEllipse(brush,420,-100,300,300);}bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}return path;}
 internal static void Core(string folder){
  var store=new Store(Path.Combine(folder,"workflows-core"));
  Check(!PersonalWorkflows.CaptureInbox(store,"","",delegate{throw new Exception();}),"Titre boîte vide");
  Check(!PersonalWorkflows.CaptureInbox(store,"Non sauvegardé","",delegate{return false;})&&store.Value.inbox.Count==0,"Capture non sauvegardée");
  PersonalWorkflows.CaptureInbox(store,"Idée chantier","Détails conservés",delegate{store.Save();return true;});var item=store.Value.inbox.Single();
  Check(new Store(store.Root).Value.settings.HomeBlocks.Any(b=>b.id=="inbox"&&b.visible),"Bloc boîte persisté");
  PersonalWorkflows.ConvertInbox(store,item.id,"task","Préparer les plans","Travail");Check(store.Value.inbox.Single().processed&&store.Value.tasks.Single().notes=="Détails conservés","Classement tâche");
  int count=store.Value.tasks.Count;bool bad=false;try{PersonalWorkflows.ConvertInbox(store,item.id,"task","Doublon","Travail");}catch(InvalidOperationException){bad=true;}Check(bad&&store.Value.tasks.Count==count,"Double classement");
  PersonalWorkflows.CaptureInbox(store,"Note","Texte",delegate{store.Save();return true;});PersonalWorkflows.ConvertInbox(store,store.Value.inbox.Last().id,"note","Note classée","Personnel");Check(store.Value.pages.Single().body=="Texte","Classement note");
  PersonalWorkflows.CaptureInbox(store,"Projet","Description",delegate{store.Save();return true;});PersonalWorkflows.ConvertInbox(store,store.Value.inbox.Last().id,"project","Mon projet visuel","");Check(store.Value.projectData.Single().description=="Description","Classement projet");
  PersonalWorkflows.CaptureInbox(store,"Idée à retrouver","Recherche accentuée",delegate{store.Save();return true;});Check(GlobalSearch.Find(store.Value,"idee retrouver","inbox").Count==1,"Recherche boîte");
  var monday=PersonalWorkflows.Monday(new DateTime(2028,1,10));var friday=monday.AddDays(4);var habit=new Habit{id="habit",name="Sport",created=monday.ToString("yyyy-MM-dd"),days=new List<int>{0,2,4}};PersonalWorkflows.Change(store,delegate{store.Value.habits.Add(habit);});
  PersonalWorkflows.ToggleHabit(store,habit.id,monday,friday);PersonalWorkflows.ToggleHabit(store,habit.id,monday.AddDays(2),friday);Check(PersonalWorkflows.Streak(store.Value.habits.Single(),friday)==2,"Série avant réalisation du jour");PersonalWorkflows.ToggleHabit(store,habit.id,friday,friday);Check(PersonalWorkflows.Streak(store.Value.habits.Single(),friday)==3,"Série jours prévus");PersonalWorkflows.ToggleHabit(store,habit.id,monday.AddDays(2),friday);Check(PersonalWorkflows.Streak(store.Value.habits.Single(),friday)==1,"Jour manqué");
  bad=false;try{PersonalWorkflows.ToggleHabit(store,habit.id,friday.AddDays(7),friday);}catch(InvalidDataException){bad=true;}Check(bad,"Habitude future");bad=false;try{PersonalWorkflows.ToggleHabit(store,habit.id,monday.AddDays(1),friday);}catch(InvalidDataException){bad=true;}Check(bad,"Jour non prévu");
  var utc=new DateTime(monday.Year,monday.Month,monday.Day,12,0,0,DateTimeKind.Utc);var task=store.Value.tasks.Single();FocusClock.Start(store,task.id,"",5,utc);FocusClock.Pause(store,utc.AddSeconds(60));FocusClock.Resume(store,utc.AddHours(1));FocusClock.Tick(store,utc.AddHours(1).AddMinutes(4));Check(store.Value.focusHistory.Single().seconds==300,"Temps focus sans pause");FocusClock.Start(store,"","",5,utc.AddHours(2));FocusClock.Cancel(store,utc.AddHours(2).AddSeconds(60));Check(store.Value.focusHistory.Sum(s=>s.seconds)==360,"Session arrêtée");
  TaskBoard.Move(store,task.id,"done");Check(store.Value.tasks.Single().completedOn==DateTime.Today.ToString("yyyy-MM-dd"),"Date de fin enregistrée");store.Value.tasks.Single().completedOn=monday.ToString("yyyy-MM-dd");store.Save();var report=PersonalWorkflows.Week(store.Value,monday);Check(report.Tasks==1&&report.FocusSeconds==360&&report.Projects==1&&report.HabitChecks==2,"Bilan hebdomadaire");
  string image=Image(folder);var cover=ProjectData.Attach(store,image);PersonalWorkflows.Change(store,delegate{var p=store.Value.projectData.Single();p.icon="★";p.cover=cover;p.blocks=new List<ProjectBlock>{new ProjectBlock{id="notes",visible=false},new ProjectBlock{id="notes"},new ProjectBlock{id="bad"}};});Check(store.Value.projectData.Single().blocks.Count==4&&store.Value.projectData.Single().blocks[0].id=="notes"&&!store.Value.projectData.Single().blocks[0].visible,"Blocs de projet");Check(ProjectVisuals.Read(ProjectData.PathFor(store,cover)).PixelWidth>0,"Couverture décodée");
  store.Value.settings.PrivacyMode=true;store.Save();Check(new Store(store.Root).Value.settings.PrivacyMode,"Mode discret persisté");
  string export=Path.Combine(folder,"workflows-export.json");store.Export(export);store.Value.inbox.Clear();store.Value.habits.Clear();store.Value.focusHistory.Clear();store.Import(export);Check(store.Value.inbox.Count==4&&store.Value.habits.Count==1&&store.Value.focusHistory.Count==2,"Import nouveaux modules");
  string archive=Path.Combine(folder,"workflows.mespace");FullBackup.Export(store,archive);var target=new Store(Path.Combine(folder,"workflows-restored"));using(var plan=FullBackup.Prepare(target,archive))FullBackup.Commit(target,plan);var restored=new Store(target.Root);Check(restored.Value.settings.PrivacyMode&&restored.Value.focusHistory.Count==2&&File.Exists(ProjectData.PathFor(restored,restored.Value.projectData.Single().cover)),"Sauvegarde couverture et modules");
  string state=Path.Combine(store.Root,"state.json");File.Delete(state);Directory.CreateDirectory(state);string inboxId=store.Value.inbox.Last().id;count=store.Value.tasks.Count;bad=false;try{PersonalWorkflows.ConvertInbox(store,inboxId,"task","Échec","Travail");}catch(IOException){bad=true;}catch(UnauthorizedAccessException){bad=true;}Directory.Delete(state);Check(bad&&!store.Value.inbox.Last().processed&&store.Value.tasks.Count==count,"Retour après échec classement");store.Save();
  var legacy=new Data();legacy.inbox=null;legacy.habits=null;legacy.focusHistory=null;legacy.projectData.Add(new ProjectSpace{name="Ancien",blocks=null});Store.Validate(legacy);Check(legacy.inbox.Count==0&&legacy.habits.Count==0&&legacy.focusHistory.Count==0&&legacy.projectData[0].blocks.Count==4,"Migration anciens formats");
 }
}
internal sealed partial class ModernWorkspace {
 void ClickPersonal(string label){var root=(DependencyObject)((ScrollViewer)content.Content).Content;LogicalControls<Button>(root).First(b=>Convert.ToString(b.Content)==label).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 internal void VerifyPersonalUi(string folder){
  dialogProbe=delegate(Window w){var fields=LogicalControls<TextBox>(w).ToList();fields[0].Text="Idée confidentielle";fields[1].Text="Détails personnels";ClickWizard(w,"Enregistrer l'idée");return true;};try{EditInbox(null);}finally{dialogProbe=null;}
  var idea=store.Value.inbox.Single();dialogProbe=delegate(Window w){LogicalControls<TextBox>(w).First().Text="Tâche issue de la boîte";ClickWizard(w,"Classer l'idée");return true;};try{ClassifyInbox(idea);}finally{dialogProbe=null;}if(!store.Value.inbox.Single().processed||store.Value.tasks.Count!=1)throw new Exception("Classement UI");
  PersonalWorkflows.CaptureInbox(store,"Une prochaine idée","À classer plus tard",delegate{store.Save();return true;});Go("Boîte de réception");Preview(Path.Combine(folder,"Boite-reception.png"));
  dialogProbe=delegate(Window w){LogicalControls<TextBox>(w).First().Text="Ma routine";ClickWizard(w,"Enregistrer l'habitude");return true;};try{EditHabit(null);}finally{dialogProbe=null;}Go("Habitudes");
  string today=DateTime.Today.ToString("ddd dd",System.Globalization.CultureInfo.GetCultureInfo("fr-FR"));var root=(DependencyObject)((ScrollViewer)content.Content).Content;LogicalControls<Button>(root).First(b=>Convert.ToString(b.Content)==today).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(store.Value.habits.Single().checks.Count!=1)throw new Exception("Habitude cochée UI");Preview(Path.Combine(folder,"Habitudes.png"));
  var project=ProjectData.Get(store.Value,"Travail");project.description="Un projet personnel organisé à votre façon.";project.cover=ProjectData.Attach(store,WorkflowsAcceptance.Image(folder));store.Save();
  dialogProbe=delegate(Window w){LogicalControls<TextBox>(w).First().Text="★";var files=LogicalControls<CheckBox>(w).First(c=>Convert.ToString(c.Content)=="Fichiers joints");files.IsChecked=false;files.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));LogicalControls<Button>(w).Where(b=>Convert.ToString(b.Content)=="↑").Skip(1).First().RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ClickWizard(w,"Enregistrer l'apparence");return true;};try{EditProjectVisual("Travail");}finally{dialogProbe=null;}
  project=store.Value.projectData.First(p=>p.name=="Travail");if(project.icon!="★"||project.blocks[0].id!="notes"||project.blocks.First(b=>b.id=="files").visible)throw new Exception("Apparence projet UI");OpenProject("Travail");Preview(Path.Combine(folder,"Projet-visuel.png"));
  var now=DateTime.UtcNow;FocusClock.Start(store,store.Value.tasks[0].id,"",1,now);FocusClock.Tick(store,now.AddMinutes(1));TaskBoard.Move(store,store.Value.tasks[0].id,"done");Go("Bilan de la semaine");Preview(Path.Combine(folder,"Bilan-semaine.png"));
  owner.TogglePrivacyMode();if(!store.Value.settings.PrivacyMode)throw new Exception("Mode discret UI");var all=String.Join("\n",LogicalControls<TextBlock>(this).Select(t=>t.Text));if(all.Contains("Idée confidentielle")||all.Contains("Détails personnels")||all.Contains("Tâche issue de la boîte")||all.Contains(store.Value.settings.DisplayName)&&!String.IsNullOrEmpty(store.Value.settings.DisplayName))throw new Exception("Contenu personnel affiché en mode discret");
  bool shown=false;dialogProbe=delegate{shown=true;return false;};try{EditInbox(store.Value.inbox[0]);}finally{dialogProbe=null;}if(shown)throw new Exception("Dialogue affiché en mode discret");Preview(Path.Combine(folder,"Mode-discret.png"));
  var widget=new DesktopWidget(owner,store);try{widget.Render(Path.Combine(folder,"Widget-discret.png"));var text=String.Join("\n",LogicalControls<TextBlock>((DependencyObject)widget.Content).Select(t=>t.Text));if(text.Contains("Tâche issue")||text.Contains("Détails personnels"))throw new Exception("Widget non masqué");}finally{widget.Shutdown();}
  owner.TogglePrivacyMode();if(store.Value.settings.PrivacyMode)throw new Exception("Retour affichage normal");
 }
}
internal sealed partial class MainForm {
 internal void VerifyPersonalUi(string folder){rendering=true;store.Value.settings.DisplayName="Nom confidentiel";store.Save();modern.VerifyPersonalUi(folder);if(uiTicker!=null)uiTicker.Dispose();modern.CancelMusic();modern.CancelModeLaunch();Stop();if(speech!=null)speech.Dispose();player.Close();}
}
internal static partial class Program {
 internal static int PersonalTest(string folder){Root=Path.GetFullPath(folder);Directory.CreateDirectory(Root);System.Windows.Forms.Application.EnableVisualStyles();try{WorkflowsAcceptance.Core(Root);using(var form=new MainForm(false))form.VerifyPersonalUi(Root);File.WriteAllText(Path.Combine(Root,"PERSONAL_PASS.txt"),"PASS: inbox capture rollback/persistence/search and atomic task/note/project classification, double classification rejection, habit scheduled dates/toggles/streak/future rejection, focus history excluding pauses and cancelled sessions, task completion dates and weekly totals, project icon/cover/blocks normalization, export/import/full backup with cover, save-failure rollback and migrations; actual WPF classification, habit checkbox, visual project editor, privacy toggle, hidden dialogs and masked widget; rendered previews. No real desktop capture, file picker or Windows notification tested.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(Root,"PERSONAL_FAIL.txt"),ex.ToString());return 1;}}
}
